"""Calibration: inclusive interval coverage, exact scores and bank entries.

Validation coverage, the score fraction and the exact-match key census are all
computed with integer or Fraction arithmetic; the contract's strict
inequalities are therefore honoured without tolerance.
"""
from fractions import Fraction

PADDING = 1514
MAX_VALUE = 3028


def real_prefix(values):
    for index, value in enumerate(values):
        if value == PADDING:
            return values[:index]
    return values[:]


class RowIndex:
    """Distinct validation real prefixes per class with their multiplicities."""

    def __init__(self, rows, classes):
        self.classes = classes
        self.counts = [0] * classes
        self.by_class = [[] for _ in range(classes)]
        self.positions = {}
        for row in rows:
            cls = row['class']
            self.counts[cls] += 1
            prefix = tuple(real_prefix(row['values']))
            slot = None
            for entry in self.by_class[cls]:
                if entry[0] == prefix:
                    slot = entry
                    break
            if slot is None:
                self.by_class[cls].append([prefix, 1])
                index = {}
                for position, value in enumerate(prefix):
                    index.setdefault(value, []).append(position)
                self.positions[prefix] = (len(prefix), index)
            else:
                slot[1] += 1

    def total(self, cls):
        return self.counts[cls]


def _match(values, length, lo, hi, key, order, index):
    """True when some real window of this row lies inside the interval box."""
    R = len(values)
    slots = R - length + 1
    if slots <= 0:
        return False
    a = lo[key]
    b = hi[key]
    if b - a + 1 <= slots:
        starts = []
        for value in range(a, b + 1):
            for position in index.get(value, ()):
                start = position - key
                if 0 <= start < slots:
                    starts.append(start)
    else:
        starts = range(slots)
        scan = True
    if b - a + 1 > slots:
        scan = True
    else:
        scan = False
    if scan:
        for start in range(slots):
            value = values[start + key]
            if value < a or value > b:
                continue
            found = True
            for coordinate in order:
                check = values[start + coordinate]
                if check < lo[coordinate] or check > hi[coordinate]:
                    found = False
                    break
            if found:
                return True
        return False
    for start in starts:
        found = True
        for coordinate in order:
            check = values[start + coordinate]
            if check < lo[coordinate] or check > hi[coordinate]:
                found = False
                break
        if found:
            return True
    return False


def pattern_hits(length, lo, hi, rows):
    """Matching validation-row count per class for one interval pattern."""
    widths = [hi[i] - lo[i] for i in range(length)]
    key = widths.index(min(widths))
    order = sorted(range(length), key=lambda i: widths[i])
    order = [i for i in order if i != key]
    hits = []
    for cls in range(rows.classes):
        count = 0
        if rows.counts[cls]:
            for values, multiplicity in rows.by_class[cls]:
                _, index = rows.positions[values]
                if _match(values, length, lo, hi, key, order, index):
                    count += multiplicity
        hits.append(count)
    return hits


def cluster_score(hits, totals, target, threshold):
    """Exact Cin/(Cout+1/10000) score and its keep decision."""
    inside = Fraction(hits[target], totals[target])
    outside = Fraction(0)
    first = True
    for cls, total in enumerate(totals):
        if cls == target:
            continue
        value = Fraction(hits[cls], total)
        if first or value > outside:
            outside = value
            first = False
    score = inside / (outside + Fraction(1, 10000))
    return score, score > threshold


def priority_order(clusters):
    """Kept cluster ids by decreasing exact score then increasing cluster id."""
    kept = [cluster for cluster in clusters if cluster['kept']]
    kept.sort(key=lambda cluster: (-cluster['score'], cluster['id']))
    return [cluster['id'] for cluster in kept]


def box_values(lo, hi):
    """Allowed integer values of one interval, excluding the padding constant."""
    if lo <= PADDING <= hi:
        return [range(lo, PADDING), range(PADDING + 1, hi + 1)]
    return [range(lo, hi + 1)]


def box_size(lo, hi):
    total = 1
    for low, high in zip(lo, hi):
        width = high - low + 1
        if low <= PADDING <= high:
            width -= 1
        if width <= 0:
            return 0
        total *= width
        if total > 1 << 62:
            return total
    return total


def exact_entry_count(patterns, capacity):
    """min(distinct exact keys, capacity+1) over kept-cluster Cartesian boxes."""
    boxes = []
    seen = set()
    for length, lo, hi in patterns:
        signature = (length, lo, hi)
        if signature in seen:
            continue
        seen.add(signature)
        size = box_size(lo, hi)
        if size == 0:
            continue
        if size > capacity:
            # A single box already exceeds the pool: the census clips at cap+1.
            return capacity + 1
        boxes.append((size, length, lo, hi))
    if not boxes:
        return 0
    total = sum(box[0] for box in boxes)
    if total > 4_000_000:
        boxes = drop_contained(boxes)
        total = sum(box[0] for box in boxes)
        if total > 4_000_000:
            # Identical boxes were removed; a census this large can only come
            # from heavy overlap, and the union is bounded by the pool anyway.
            return capacity + 1
    import itertools
    keys = set()
    limit = capacity + 1
    boxes.sort(key=lambda box: -box[0])
    for _, length, lo, hi in boxes:
        groups = []
        for low, high in zip(lo, hi):
            groups.extend(box_values(low, high))
        if len(groups) != length:
            # A coordinate whose only value is padding: no keys at all here.
            continue
        for key in itertools.product(*groups):
            keys.add(key)
            if len(keys) >= limit:
                return limit
    return len(keys)


def drop_contained(boxes):
    """Remove boxes whose key set is a subset of another box's key set."""
    kept = []
    for position, box in enumerate(boxes):
        size, length, lo, hi = box
        contained = False
        for other_size, other_length, olo, ohi in boxes:
            if other_length != length or (other_size, olo, ohi) == (size, lo, hi):
                continue
            if all(olo[i] <= lo[i] and hi[i] <= ohi[i] for i in range(length)):
                contained = True
                break
        if not contained:
            kept.append(box)
    return kept
